// A daily message proves the monitor itself is alive. If it stops arriving, the monitor is the thing that failed.
const sd = $getWorkflowStaticData('global'), day = Date.now() - 864e5;
const recent = (sd.history || []).filter(h => h.t > day), checked = (sd.checked || []).filter(t => t > day).length;
const by = {}; for (const h of recent) by[h.kind] = (by[h.kind] || 0) + 1;
const parts = Object.entries(by).map(([k, n]) => `${n} ${k.replace(/_/g, ' ')}`);
return [{ json: { text: `${$('Config').first().json.workflow_label}: ${checked} checks in the last 24 hours. ${parts.length ? 'Problems found: ' + parts.join(', ') + '.' : 'No silent failures found.'}` } }];

// checks_json in Config lists the workflows to watch. See the sticky note for every field.
let checks = [];
try { checks = JSON.parse($('Config').first().json.checks_json); } catch (e) { throw new Error('checks_json in Config is not valid JSON: ' + e.message); }
return checks.filter(c => c.workflow_id && !/^REPLACE/.test(c.workflow_id)).map(c => ({ json: Object.assign({ max_gap_minutes: 0, count_node: '', min_items: 1,
  record_check_url: '', record_min: 1, alert_on_errors: false }, c, { ref: c.name || c.workflow_id }) }));

// One item per check with everything Evaluate needs: the check, the workflow and its recent runs, and the record count if set.
const check = $('One item per check').item.json, wfj = $('Get workflow').item.json, r = $('Get recent runs').item.json;
let record = null;
if (check.record_check_url) {
  const b = $('Check expected record').item.json;
  record = Array.isArray(b) ? b.length : Number(b.count ?? b.total ?? b.total_count ?? (b.data || b.results || b.items || []).length);
}
return { json: { check, workflow: { name: wfj.name, active: wfj.active }, runs: r.data || [], record } };

// Three watched workflows with the problems this catches, shaped like the n8n API. Run "Test workflow" to see the alerts.
const ago = m => new Date(Date.now() - m * 60000).toISOString();
const run = (id, m, status, node, n) => ({ id, status, mode: 'trigger', startedAt: ago(m), stoppedAt: ago(m - 1),
  data: { resultData: { lastNodeExecuted: node, runData: { [node]: [{ data: { main: [Array.from({ length: n }, (_, i) => ({ json: { i } }))] } }] } } } });
const base = { max_gap_minutes: 0, count_node: '', min_items: 1, record_check_url: '', record_min: 1, alert_on_errors: true };
return [
  { json: { check: Object.assign({}, base, { workflow_id: '101', name: 'Nightly order sync', count_node: 'Upsert orders', ref: 'Nightly order sync' }),
    workflow: { name: 'Nightly order sync', active: true }, runs: [run('9001', 30, 'success', 'Upsert orders', 0), run('8990', 1470, 'success', 'Upsert orders', 42)], record: null } },
  { json: { check: Object.assign({}, base, { workflow_id: '102', name: 'Hourly stock update', max_gap_minutes: 90, ref: 'Hourly stock update' }),
    workflow: { name: 'Hourly stock update', active: true }, runs: [run('8700', 300, 'success', 'Update stock', 18)], record: null } },
  { json: { check: Object.assign({}, base, { workflow_id: '103', name: 'Website leads to CRM', record_check_url: 'https://example.com/leads-today', record_min: 1, ref: 'Website leads to CRM' }),
    workflow: { name: 'Website leads to CRM', active: false }, runs: [run('8650', 600, 'success', 'Create contact', 1)], record: 0 } }
];

// Each finding has a key, so the same problem is reported once, not every 15 minutes.
const cfg = $('Config').first().json, base = cfg.n8n_base_url.replace(/\/$/, ''), now = Date.now();
const since = now - Number(cfg.lookback_hours || 24) * 36e5, out = [];
const count = (run, node) => {
  const rd = ((run.data || {}).resultData || {}).runData || {};
  const name = node || ((run.data || {}).resultData || {}).lastNodeExecuted;
  if (!name || !rd[name]) return { name: name || 'last step', n: null };
  return { name, n: rd[name].reduce((s, r) => s + (((r.data || {}).main || [])[0] || []).length, 0) };
};
for (const it of $input.all()) {
  const { check: c, workflow: wf, runs, record } = it.json, name = c.name || wf.name || c.workflow_id;
  const add = (kind, detail, key, exec) => out.push({ json: { time: new Date().toISOString(), workflow: name, workflow_id: c.workflow_id, kind, detail, key,
    link: exec ? `${base}/workflow/${c.workflow_id}/executions/${exec}` : `${base}/workflow/${c.workflow_id}` } });
  if (wf.active === false) add('switched_off', 'The workflow is inactive, so its triggers will not fire.', `off:${c.workflow_id}:${new Date().toISOString().slice(0, 10)}`);
  const last = runs.reduce((m, r) => Math.max(m, Date.parse(r.startedAt) || 0), 0);
  if (Number(c.max_gap_minutes) > 0 && now - last > c.max_gap_minutes * 60000)
    add('missed_schedule', last ? `No run for ${Math.round((now - last) / 60000)} minutes (expected at least every ${c.max_gap_minutes}).` : 'No runs found at all.', `gap:${c.workflow_id}:${last}`);
  for (const r of runs) {
    if ((Date.parse(r.startedAt) || 0) < since) continue;
    r.status = r.status || (r.finished ? 'success' : r.stoppedAt ? 'error' : 'running');
    if (['error', 'crashed'].includes(r.status)) { if (c.alert_on_errors) add('failed_run', `The run ended with status "${r.status}".`, `err:${r.id}`, r.id); continue; }
    if (r.status !== 'success') continue;
    const k = count(r, c.count_node);
    if (k.n === null) add('empty_run', `Finished green, but "${k.name}" never ran (a filter or IF stopped everything).`, `empty:${r.id}`, r.id);
    else if (k.n < Number(c.min_items)) add('empty_run', `Finished green with ${k.n} item${k.n === 1 ? '' : 's'} out of "${k.name}" (expected at least ${c.min_items}).`, `empty:${r.id}`, r.id);
  }
  if (record !== null && !(record >= Number(c.record_min)))
    add('missing_record', `Expected at least ${c.record_min} record${c.record_min == 1 ? '' : 's'} at the check URL, found ${isNaN(record) ? 'none' : record}.`, `rec:${c.workflow_id}:${new Date().toISOString().slice(0, 13)}`);
}
return out;

// Drops findings already reported (keys kept in static data, saved on production runs only) and records the history for the daily summary.
const sd = $getWorkflowStaticData('global'), seen = sd.seen || [], now = Date.now(), out = [];
sd.checked = (sd.checked || []).filter(t => now - t < 864e5).concat([now]).slice(-200);
for (const i of $input.all()) { if (seen.includes(i.json.key)) continue; seen.push(i.json.key); out.push({ json: i.json }); }
sd.seen = seen.slice(-5000);
sd.history = (sd.history || []).filter(h => now - h.t < 7 * 864e5).concat(out.map(o => ({ t: now, kind: o.json.kind, name: o.json.workflow }))).slice(-2000);
return out;

const L = { empty_run: 'Empty run', missed_schedule: 'Missed schedule', missing_record: 'Missing record', switched_off: 'Switched off', failed_run: 'Failed run' };
const rows = $input.all().map(i => i.json);
const lines = rows.map(r => `• *${L[r.kind] || r.kind}*: ${r.workflow}. ${r.detail} <${r.link}|Open>`);
return [{ json: { count: rows.length, text: `${$('Config').first().json.workflow_label}: ${rows.length} silent failure${rows.length === 1 ? '' : 's'}\n` + lines.join('\n'),
  email: rows.map(r => `${L[r.kind] || r.kind}: ${r.workflow}\n${r.detail}\n${r.link}`).join('\n\n') } }];

